import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"数字人生计划","description":"","frontmatter":{"title":"数字人生计划","date":"2026-01-08T00:00:00.000Z","category":"生活指南","tags":["智能生活"],"order":5},"headers":[],"relativePath":"articles/life/smart-life/shuzirensheng.md","filePath":"articles/life/smart-life/shuzirensheng.md","articleMeta":{"updated":"2026-01-08","words":1917,"minutes":5}}`),a={name:`articles/life/smart-life/shuzirensheng.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<blockquote><p>互联网时代，数据的稳定存储是十分昂贵的。丢失手机，就会丢失照片和聊天记录。曾经风光一时的天涯论坛关站，无数神贴一夜归零。这警示我们：做好数字人生计划，留存有价值的信息，享受更便捷的数字生活。</p></blockquote><h2 id="_1-生活云-icloud——个人-家庭相册-无感知云端" tabindex="-1">1.生活云：iCloud——个人&amp;家庭相册，无感知云端 <a class="header-anchor" href="#_1-生活云-icloud——个人-家庭相册-无感知云端" aria-label="Permalink to “1.生活云：iCloud——个人&amp;家庭相册，无感知云端”">​</a></h2><p>如果苹果用户，iCloud 是无可替代的最佳选择，唯一的缺点就是2TB需要68元/月的价格，相较于百度云、阿里云等比较贵，但是家庭多人使用还是相当划算。iCloud主要特性/优势如下:</p><p>（1）丝滑的云端和本地体验：需要注意iCloud不是网盘的概念，而是无感知的云端同步，因此本地删除、云端同步删除，很多人误操作导致数据丢失。有人就会问了，那我手机只有256GB，云端2TB岂不是白费？ 打开“优化iPhone储存空间”的功能，在设备本地将自动替换为小分辨率版本，全分辨率版本可以随时取回。压缩和取回的过程都是无感的。有了整个功能，上万张照片可以安全无虞的储存，并在设备本地查看、分享。无感知云端的特性是百度云等第三方云盘无法实现的。</p><p><img src="/images/Picsew_20260108105039-1774860089283-27.jpeg" alt="Picsew_20260108105039.jpeg" width="1174" height="1080"></p><p>（2）兼顾个人使用与家庭共享：iCloud相册可以划分为个人相册和共享相册，相册中既可以保存自己的隐私照片，也可以经过手动确认后将照片添加到共享相册。无须通过Airdrop或者微信传输照片，丝滑分享家人的照片且不重复占用存储空间。共享相册可以指定共享的家庭成员范围；共享相册中的照片可以共同编辑、删除等。</p><p>（3）跨设备同步的文件云盘：一个丝滑的文件同步盘，可以在多设备之间同步各类文件。非苹果设备例如Windows下载安装iCloud程序后也支持使用。</p><p>（4）自动化手机备份：手机全局备份，包括应用软件和缓存，例如微信聊天记录等。手机不怕丢。</p><p>（5）更多功能见<a href="https://support.apple.com/zh-cn/guide/icloud/mm203ae070a2/icloud" target="_blank" rel="noreferrer">APPLE官方文档</a></p><h2 id="_2-影音生活-夸克云盘——资源网络资源、无人机拍摄素材" tabindex="-1">2. 影音生活：夸克云盘——资源网络资源、无人机拍摄素材 <a class="header-anchor" href="#_2-影音生活-夸克云盘——资源网络资源、无人机拍摄素材" aria-label="Permalink to “2. 影音生活：夸克云盘——资源网络资源、无人机拍摄素材”">​</a></h2><p>对于非核心的个人数据，我们追求的是“大空间”和“下载速度”。88Vip赠送的夸克网盘会员，还是比较好用。不需要额外开会员，就可以享受到6TB存储空间和高速下载。用于云端储存各类网络资源、比较良心。找夸克资源：通过百度、谷歌、Telegram频道搜索，保存至自己的夸克网盘。PC/电视端下载夸克PC/TV版本，登陆后即可在大屏观看，88VIP赠送的会员可以享受基本的4K流媒体播放。</p><p>附Telegram资源频道：<a href="https://t.me/Quark_0" target="_blank" rel="noreferrer">https://t.me/Quark_0</a></p><p>夸克网盘搜索：<a href="https://pan.funletu.com/" target="_blank" rel="noreferrer">https://pan.funletu.com/</a></p><p>下载夸克TV版：<a href="https://pan.quark.cn/" target="_blank" rel="noreferrer">https://pan.quark.cn/</a> ，下载安装包后通过U盘在电视上安装。</p><h2 id="_3-个人记录相关——要求云同步、随时可以导出。" tabindex="-1">3. 个人记录相关——要求云同步、随时可以导出。 <a class="header-anchor" href="#_3-个人记录相关——要求云同步、随时可以导出。" aria-label="Permalink to “3. 个人记录相关——要求云同步、随时可以导出。”">​</a></h2><p>拒绝封闭平台，数据必须可导出。你的思想火花是最宝贵的资产，不要将它们锁在可能随时跑路的小众 App 或随时被封号的社交平台里。</p><p>（1）轻量速记：使用手机厂商自带的备忘录功能，并打开同步功能，通常会赠送5GB空间。</p><p>（2）使用小红书/微博/微信公众号/微信收藏可以作为辅助手段，可能因触发敏感词或平台封禁。</p><p>（3）不建议使用各类小厂商制作的日记、笔记软件，其云同步功能通常收费昂贵，且无法导出数据，有倒闭/跑路风险。</p><p>（4）进阶：使用<a href="https://b3log.org/siyuan/download.html" target="_blank" rel="noreferrer">思源笔记</a>等开源平台自行搭建笔记程序，确保数据属于自己、随时可以导出和备份。（需自行购买或搭建 S3 服务）</p><h2 id="_4-普通用户不建议nas" tabindex="-1">4. 普通用户不建议NAS <a class="header-anchor" href="#_4-普通用户不建议nas" aria-label="Permalink to “4. 普通用户不建议NAS”">​</a></h2><p>除了存储硬件设备的投资成本，还有容灾备份、电费、应急电源的持续投入，如果还需要外网访问，还需要折腾光猫或者中转，速度也不理想。</p><h2 id="_5-隐私建议" tabindex="-1">5.隐私建议 <a class="header-anchor" href="#_5-隐私建议" aria-label="Permalink to “5.隐私建议”">​</a></h2><p>（1）数据上云后，隐私是第一要义。从国内厂商来看，使用苹果的iCloud隐私性有较高保障。</p><p>（2）使用网盘程序时，分享文件或者照片须设置密码。</p><p>（3）无论是什么手机，打开“限制访问相册”的功能，否则理论上APP具备后台读取全部照片的权限。</p><p>（4）分享照片注意照片中的元数据 (EXIF)：照片中可能包含了拍摄时间、手机型号、拍摄的经纬度。向陌生人分享照片原图需谨慎（微信发送时会自动清除照片的拍摄时间和地点，好处是默认隐私保护，坏处是不利于向家人分享照片）</p><h2 id="_6-ai小结" tabindex="-1">6.AI小结 <a class="header-anchor" href="#_6-ai小结" aria-label="Permalink to “6.AI小结”">​</a></h2><p>用 iCloud 存生活（隐私+无感），用夸克存资源（量大+娱乐），用本地化笔记存思想（自主+安全），这就是现阶段最实用的数字生存法则。</p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};